    }
  }
};

createCanvas(1600, 900);
noFill();
t = 0;
draw = () => {
  t += 0.004;
  background(10);
  strokeWeight(1.4);
  const cols = 36;
  const rows = 22;
  for (let row = 1; row < rows; row += 1) {
    for (let col = 1; col < cols; col += 1) {
      const x = (col / cols) * width;
      const y = (row / rows) * height;
      const angle = noise(x * 0.0022, y * 0.0022, t) * TWO_PI * 1.5;
      stroke(255, 24 + ((col + row) % 3) * 10);
      line(x, y, x + cos(angle) * 30, y + sin(angle) * 30);
    }
  }
};

